def calculate_average_rating(movies):
    total_rating = 0
    num_movies = len(movies)

    for movie in movies:
        total_rating += movie["rating"]

    average_rating = total_rating / num_movies

    return round(average_rating, 2)

def find_unique_nietzsche_quotes(nietzsche_quotes, camus_quotes):
    unique_quotes = []
    for quote in nietzsche_quotes:
        if quote not in camus_quotes:
            unique_quotes.append(quote)
    return unique_quotes

def manage_beer_inventory(beer_tuples):
    beer_dict = {}
    for beer, kegs in beer_tuples:
        if kegs > 0:
            beer_dict[beer] = kegs
    return beer_dict

def count_distinct_powers(nums):
    powers = set()
    for base in nums:
        for exponent in nums:
            powers.add(base ** exponent)
    return len(powers)

def filter_words(word_list, filter_words):
    filtered_list = []
    for word in word_list:
        if word.lower() not in [w.lower() for w in filter_words]:
            filtered_list.append(word)
    return filtered_list

def sum_even_numbers(numbers):
    total = 0
    for num in numbers:
        if num % 2 == 0:
            total += num
    return total

